def pick_greeting(hour: int, name: str, lang: str = "en", formal: bool = False, mood: str = "ok") -> str:
    """Choose a greeting based on the time of day, language, formality, and mood."""
    if lang == "en":
        if hour < 12:
            if formal:
                if mood == "great":
                    return f"Good morning, {name}. What a fine day."
                elif mood == "bad":
                    return f"Good morning, {name}. I hope it improves."
                else:
                    return f"Good morning, {name}."
            else:
                if mood == "great":
                    return f"Morning, {name}! Feeling good?"
                elif mood == "bad":
                    return f"Morning, {name}. Rough one?"
                else:
                    return f"Morning, {name}!"
        elif hour < 18:
            if formal:
                if mood == "great":
                    return f"Good afternoon, {name}. Splendid."
                elif mood == "bad":
                    return f"Good afternoon, {name}. Chin up."
                else:
                    return f"Good afternoon, {name}."
            else:
                if mood == "great" or mood == "ok":
                    return f"Hey {name}!"
                else:
                    return f"Hey {name}. Hang in there."
        else:
            if formal:
                return f"Good evening, {name}."
            else:
                if mood == "bad":
                    return f"Evening, {name}. Long day?"
                else:
                    return f"Evening, {name}!"
    elif lang == "es":
        if hour < 12:
            if formal:
                return f"Buenos dias, {name}."
            else:
                return f"Buenas, {name}!"
        elif hour < 20:
            if formal and mood != "bad":
                return f"Buenas tardes, {name}."
            elif formal:
                return f"Buenas tardes, {name}. Animo."
            else:
                return f"Buenas, {name}!"
        else:
            return f"Buenas noches, {name}."
    elif lang == "fr":
        if hour < 18:
            if formal:
                return f"Bonjour, {name}."
            else:
                return f"Salut, {name}!"
        else:
            return f"Bonsoir, {name}."
    else:
        if formal:
            return f"Hello, {name}."
        else:
            return f"Hello, {name}!"

from helloworld.greet import hello, hello_many, shout


def test_hello_default():
    assert hello() == "Hello, World!"


def test_hello_named():
    assert hello("Jeff") == "Hello, Jeff!"


def test_hello_empty_falls_back_to_world():
    assert hello("") == "Hello, World!"


def test_hello_many_empty():
    assert hello_many([]) == "Hello, World!"


def test_hello_many_one():
    assert hello_many(["Jeff"]) == "Hello, Jeff!"


def test_hello_many_two():
    assert hello_many(["Jeff", "Ann"]) == "Hello, Jeff and Ann!"


def test_hello_many_three():
    assert hello_many(["Jeff", "Ann", "Bob"]) == "Hello, Jeff, Ann and Bob!"


def test_shout():
    assert shout("Hello, Jeff!") == "HELLO, JEFF!!!"

from helloworld.names import clean_name, initials


def test_clean_name_trims():
    assert clean_name("  Jeff ") == "Jeff"


def test_initials_two_parts():
    assert initials("Jeff Public") == "J.P."
